class UnionFind:
    """Find and union algorithm for disjoint sets."""
    def __init__(self, n: int) -> None:
        self.parent = list(range(n))
        self.size = [1] * n

    def find_parent(self, i: int) -> int:
        return self.parent[i] if self.size[i] != 1 else self.find_parent(self.parent[i])

    def union(self, i, j) -> bool:
        # Union the set with index i with the set with index j.
        if not (0 < self.find_parent(i) < n or 0 < self.find_parent(j) < n):
