def is_bipartite(graph, colors):
    """ Check if a given graph is bipartite using a bfs. """

    n = len(graph)
    visited = [False] * n
    visited[colors[0]] = True

    queue = deque([colors[0]])

    while queue:
        node = queue.popleft()
        for i, color in enumerate(graph[node]):
            if not visited[i]:
                colors[i] = 1 - colors[node]
                visited[i] = True
                queue.append(colors[i])
            elif color != 1 - colors[node]:
                return False

    return True

def process_clauses(n, clauses):
    """ Process k constraints on subgraphs. """

    graph = [[False] * n for _ in range(n)]
