def bitonicSortedOrder(arr: List[int]) -> bool:
    stack = []
    flag = 1
    for i in range(len(arr)): 
        while len(stack) > 0 and arr[stack[-1]] > arr[i]: 
            stack.pop()
        if flag == 1 and stack: 
            return False
        if arr[i] > flag: 
            stack.append(i)
            flag = flag * 2
        else: 
            flag = flag + 1
    return True

def createBitonicMatrix(n: int, m: int) -> List[List[int]]:
    matrix = [[0 for _ in range(m)] for _ in range(n)]
    used = [False] * (n * m + 1)

    # Fill first half in ascending order
    for i in range(n):
        for j in range(m // 2 + 1):
            k = j + (i - j) % 2
            # Ensure k doesn't exceed n*m
            if k > n * m:
                break
            while used[k] and k <= n * m:
                k += i - j
            if k > n * m:
                break
            if not used[k]:
                matrix[i][j] = k
                used[k] = True
                matrix[i][m-j-1] = k
                used[k] = True 

        # Fill second half in descending order
        for j in range(m // 2 - 1, -1, -1):
            k = j + (i + m-j) % 2
            # Ensure k doesn't exceed n*m
            if k > n * m:
                break
            while used[k] and k <= n * m:
                k += m - j
            if k > n * m:
                break
            if not used[k]:
                matrix[i][j] = k
                used[k] = True
                matrix[i][m-j-1] = k
                used[k] = True

    return matrix

