    additional_edges = 0
    for a in range(1, n + 1):
        for b in edges[a]:
            if edges[b][a] == 1:
                additions = max(n - (2 * required_edges + additional_edges + 2), 0)
                additional_edges += additions
                required_edges += 1

    return required_edges + additional_edges

n, m = map(int, input().split())
print(solution(n, m))
