import sys

def compute_dice_probabilities(A, B):
    n = len(A)
    a_matrix = [[0.0] * n for _ in range(n)]
    b_matrix = [[0.0] * n for _ in range(n)]

    for i in range(n):
        a_probability = 0
        for j in range(n):
            a_probability += A[j] * B[i]
        for j in range(n):
            a_matrix[i][j] = A[j] * B[i] / a_probability

        b_probability = 0
        for j in range(n):
            b_probability += A[i] * B[j]
        for j in range(n):
            b_matrix[i][j] = A[i] * B[j] / b_probability

    for i in range(n):
        a_values_sum = sum(a_matrix[i])
        b_values_sum = sum(b_matrix[i])
        if abs(a_values_sum - 1) > 1e-6 or abs(b_values_sum - 1) > 1e-6:
            print("Error in the probability distribution for dice dice i")
            return

    return a_matrix, b_matrix

